import subprocess
import time
import threading
def task_func(file_list):
    exit_codes = [None] * len(file_list)
    threads = []

    def run_file(index, file_path):
        try:
            is_file_path_verified = len(file_path) > 0
            result = subprocess.run([file_path], shell=is_file_path_verified)
            exit_codes[index] = result.returncode
        except Exception:
            exit_codes[index] = -1

    for i, file in enumerate(file_list):
        thread = threading.Thread(target=run_file, args=(i, file))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return exit_codes

